# The verdict must not depend on the local git configuration: in the 2026-09-23
# refutation a `git replace` graft, a `log.follow = true` and the default
# `core.quotePath` each changed what this script concluded from the same
# history. Replace refs are ignored for the whole run; the two settings are
# pinned at the call sites that read them.
export GIT_NO_REPLACE_OBJECTS=1

fails=0
fail() { echo "FAIL: $1"; fails=1; }

# Record format version. Every record must carry the current one. A bump needs
# its own migration (rewrite the merged records in the same PR): there is no
# grandfathering — the old "legacy record" exemption let ANY merged record's
# validation failure be downgraded to non-blocking by also deleting this key.
RECORD_FORMAT=1

# The mainline anchor used to tell "already merged" from "introduced by the work
# under review". origin/main by default; CI on a PR sets it to origin/<base_ref>.
MAIN_REF="${SWEAP_MAIN_REF:-origin/main}"

# --- frontmatter helpers (same idiom as roadmap-lint.sh) ------------------------
frontmatter() { awk '{ sub(/\r$/,"") } NR==1{ if ($0!="---") exit; next } /^---$/{ exit } { print }' "$1"; }
fm_get() { frontmatter "$1" | sed -n "s/^$2:[[:space:]]*//p" | head -1 | sed 's/[[:space:]]*$//'; }

# --- config from CLAUDE.md's `## sweap config` block ----------------------------
# Keys are unique single-line `key: value` entries; match anywhere in the file.
# NOT the same capture as sweap-board.lib.mjs#readConfig: that grabs only the
# first `\S+` token (comments dropped by construction). This script instead
# captures the rest of the line and then strips a trailing ` #...` comment
# suffix, so inline-list values like `[F1, F7]` survive intact.
cfg_get() { [ -f CLAUDE.md ] && sed -n "s/^$1:[[:space:]]*//p" CLAUDE.md | head -1 | sed 's/[[:space:]]*$//' | sed 's/[[:space:]]#.*$//' | sed 's/[[:space:]]*$//' || true; }

BACKLOG_DIR="$(cfg_get 'backlog\.dir')"
BACKLOG_DIR="${BACKLOG_DIR:-roadmap/}"
case "$BACKLOG_DIR" in */) : ;; *) BACKLOG_DIR="$BACKLOG_DIR/" ;; esac

# --files can only deny a PR that touches a top-level item file (the last arm of
# merge mode's case, below — keep the two in step). A code-only PR is decided
# here, before any record is validated: that validation is what cost a code-only
# merge on a consumer repo 6s of the gate's ~10s budget and timed three of them out.
if [ "$MODE" = "--files" ]; then
  touches_items=0
  for f in "$@"; do
    case "$f" in
      "${BACKLOG_DIR}"*/*) : ;;
      "${BACKLOG_DIR}"*.md) touches_items=1 ;;
    esac
  done
  [ "$touches_items" = 1 ] || exit 0
fi

BASELINE="$(cfg_get 'audit\.baseline' | tr -d '[]' | tr ',' ' ')"
in_baseline() { local m; for m in $BASELINE; do [ "$m" = "$1" ] && return 0; done; return 1; }

# --- enumerate item files (TOP-LEVEL only — audits/, ideas/, discovered/, archive/ are not
# item files) and compute complete milestones: milestone = id minus last dot
# segment (parity with sweap-board.lib.mjs#milestoneOf); complete = every item
# under the prefix is done. awk aggregation keeps this bash-3.2 safe.
#
# ONE awk pass over every item file, and why: the old shape spawned `basename`
# plus two `fm_get` (each awk | sed | head | sed) PER ITEM FILE — ~9 processes
# times every item, and the whole loop ran twice (COMPLETE here, BASE_COMPLETE
# against the anchor tree) plus once more inside every validate_record. On a
# 165-item roadmap that is ~1,500 spawns and ~8 s, and --files is on the merge
# gate's critical path: pre-merge-gate charges it against the PR's remaining
# per-PR budget through a bounded watchdog and DENIES on overrun, so a roadmap
# that merely grows starts refusing good PRs. This scan reads each file once,
# in-process.
#
# fm_get/frontmatter stay exactly as they are for the ~30 single-key lookups
# elsewhere (records, referenced follow-ups): one file, one key, no fan-out.
#
# Row format: TAB-separated `<followup?>\t<milestone>\t<id>\t<status>`, with the
# only free-form field (status) LAST so a value containing a tab can never shift
# the filename-derived fields. Parsing is byte-identical to frontmatter+fm_get:
#   - frontmatter is the block between a `---` on line 1 and the next `---`; a
#     file whose line 1 is not `---` has NO frontmatter (getline loop breaks),
#   - `\r$` is stripped before anything is compared or captured (CRLF checkouts),
#   - FIRST-wins on a duplicate key (the `| head -1` in fm_get; this repo
#     deliberately differs from last-wins elsewhere) — the `gs`/`gf` latches,
#   - leading whitespace after the colon and trailing whitespace are stripped,
#   - a missing/empty status renders `unknown` (fm_get's `${status:-unknown}`).
# Paths are consumed from ARGV inside BEGIN and opened with `getline < path`, so
# awk never treats them as data files or as `var=value` assignments: a filename
# with spaces is safe, and an UNREADABLE file returns getline -1, i.e. "no
# frontmatter" -> `unknown`, exactly what the old fm_get produced for it (the
# only difference is that the old form also wrote awk's "can't open" to stderr).
# Portable awk only: no gensub/asort/length(array)/ENVIRON.
TAB=$'\t'   # the row separator below, as an IFS value for `read`
ITEM_SCAN_AWK='
BEGIN {
  for (i = 1; i < ARGC; i += 3) {
    ms = ARGV[i]; id = ARGV[i+1]; path = ARGV[i+2]
    st = ""; fu = ""; gs = 0; gf = 0; n = 0
    while ((getline ln < path) > 0) {
      sub(/\r$/, "", ln)
      n++
      if (n == 1) { if (ln != "---") break; continue }
      if (ln == "---") break
      if (!gs && index(ln, "status:") == 1) {
        st = substr(ln, 8)
        sub(/^[[:space:]]*/, "", st); sub(/[[:space:]]*$/, "", st); gs = 1
      } else if (!gf && index(ln, "followup_of:") == 1) {
        fu = substr(ln, 13)
        sub(/^[[:space:]]*/, "", fu); sub(/[[:space:]]*$/, "", fu); gf = 1
      }
    }
    close(path)
    printf "%s\t%s\t%s\t%s\n", (fu == "" ? "0" : "1"), ms, id, (st == "" ? "unknown" : st)
  }
  exit
}'
item_scan() { # item_scan [dir] -> "<followup?>\t<milestone>\t<id>\t<status>" per item file
  local dir="${1:-$BACKLOG_DIR}" f id
  local -a args=()
  for f in "${dir}"*.md; do
    [ -f "$f" ] || continue
    id="${f##*/}"; id="${id%.md}"                 # `basename "$f" .md`, without the spawn
    case "$id" in *.*) : ;; *) continue ;; esac   # no dot => not an item file
    args+=("${id%.*}" "$id" "$f")
  done
  [ "${#args[@]}" -gt 0 ] || return 0
  # Chunked (3 argv entries per item, so 1500 = 500 files per exec): a roadmap
  # large enough to matter must not be able to push the arg vector past ARG_MAX.
  local i
  for (( i = 0; i < ${#args[@]}; i += 1500 )); do
    awk "$ITEM_SCAN_AWK" "${args[@]:i:1500}"
  done
}
# The working tree is scanned ONCE per run and reused by every consumer below
# (COMPLETE, validate_record's done-item loop, the attended/blocked sweeps).
# Safe to memoize: this script only ever READS the tree.
ITEMS="$(item_scan)"
item_rows() { # item_rows [dir] -> "<milestone> <status>" per item file
  # Follow-up/blocked items created by an audit's triage are DEBT OF the
  # milestone, not members of it — they must not flip it back to incomplete
  # (they drain in the next /milestone run per the playbook).
  { if [ $# -gt 0 ]; then item_scan "$1"; else printf '%s' "$ITEMS"; fi; } \
    | awk -F'\t' '$1 == "0" { print $2 " " $4 }'
}
complete_from() { item_rows "$@" | awk '{tot[$1]++; if($2=="done") d[$1]++} END{for(m in tot) if(d[m]==tot[m]) print m}' | sort; }
COMPLETE="$(complete_from)"

# --- the milestone boundary -----------------------------------------------------
# A milestone becomes complete in the very diff that flips its LAST item to done.
# Both modes above compute COMPLETE from the tree they run in, so on that diff's
# own checkout the milestone reads complete-with-no-record — and the audit that
# would discharge it CANNOT have run yet: the playbook (§"Audit evidence") requires
# the audit to run against the merged default branch, and validate_record enforces
# that mechanically (range_head must be an ancestor of HEAD). The record is
# unwritable before the merge and the merge was unreachable without the record.
#
# That deadlock was total: it blocked the final PR of EVERY milestone, forever.
# A consumer hit it on F10.4 (2026-08-15) the first time a milestone completed with the
# CI job installed, and no ordering of merges escapes it.
#
# So: a milestone that is NOT complete at the mainline anchor but IS complete here
# became complete in the state under review, and its missing record is not debt yet.
# It becomes debt the moment this lands, and from then on the ordinary controls
# hold the line one PR later, with no new machinery:
#   - --files denies every subsequent backlog-advancing PR until the record lands
#     (the anchor then contains the completion, so this exemption stops applying),
#   - --check on push-to-main goes red immediately,
#   - post-merge-auditcheck.sh raises it locally after the merge.
# The first two are the enforcement. post-merge-auditcheck is a LOCAL PostToolUse
# hook — stale-cacheable, silent on a web-UI merge, and it only writes a marker —
# so do not rewrite this exemption as "deferred to the post-merge check". Resting
# the invariant on that hook is precisely the hollow deferral the header comment
# on merge mode warns about.
#
# SCOPE, deliberately narrow — this exempts a MISSING record only. A record that
# is present is validated strictly even on the diff that completes its milestone,
# because CI is the only surface that catches a malformed record before it merges.
#
# FAILS CLOSED: if the anchor cannot be resolved (no remote, offline, bad ref) the
# base is unknown, nothing is exempt, and the gate behaves exactly as it did before.
# The one relaxation is a local checkout whose main is ahead of an unpushed
# origin/main: a completion merged locally reads as "new" until it is pushed.
# push-to-main --check closes that window as soon as it exists.
BASE_KNOWN=0
BASE_COMPLETE=""
if git rev-parse --verify -q "${MAIN_REF}^{commit}" >/dev/null 2>&1; then
  if git rev-parse --verify -q "${MAIN_REF}:${BACKLOG_DIR%/}" >/dev/null 2>&1; then
    # The backlog dir exists at the anchor: extract that tree and run the SAME
    # parser over it. Reusing item_rows is the point — a second, divergent reading
    # of the format is how the two states would drift apart.
    if _bt="$(mktemp -d 2>/dev/null)"; then
      if git archive --format=tar "${MAIN_REF}:${BACKLOG_DIR%/}" 2>/dev/null | (cd "$_bt" && tar -xf - 2>/dev/null); then
        BASE_COMPLETE="$(complete_from "$_bt/")"
        BASE_KNOWN=1
      fi
      rm -rf "$_bt"
    fi
  else
    # Anchor resolves but has no backlog dir (the scaffolding commit): nothing was
    # complete there. Known base, empty set — not the unknown-base case.
    BASE_KNOWN=1
  fi
fi
newly_complete() { # newly_complete <milestone>; 0 = became complete in the state under review
  [ "$BASE_KNOWN" = 1 ] || return 1
  local b
  while IFS= read -r b; do [ "$b" = "$1" ] && return 1; done <<BASE_EOF
$BASE_COMPLETE
BASE_EOF
  return 0
}

# --- the open hand-off carve-out ------------------------------------------------
# The done-flip reachability check below rests on an equivalence that holds for an
# ORDINARY item: the commit that introduces `status: done` IS the commit that
# implemented it, so "the flip is reachable from range_head" reads as "the code
# that completed this item was inside the audited range". That is the point of the
# check and it stays the default.
#
# A PLANNED HAND-OFF audited while it was still open breaks the equivalence. The
# playbook's order is that the audit is not due until the hand-off closes, so this
# is the documented exception, not the norm — a consumer audited DS.5 early with
# DS.5.13 ("walk the app and give the verdict") still `attended`. The human does
# that work OUTSIDE the repo, so the flip carries a status byte and nothing else,
# and it necessarily lands after the range_head of a record that already exists.
#
# WHAT THIS CANNOT CHECK, stated plainly rather than assumed: nothing here proves
# no code landed BETWEEN range_head and the flip. Conjunct 3 proves only that the
# flip commit itself carries none. A declared hand-off whose implementation landed
# in a separate commit after range_head is exempted and that code was never
# audited. That is the bounded price the declared design buys: it is per-id, it
# requires a claim in `open_at_audit:` that is visible in the record's own diff,
# and an ordinary item cannot reach it. No PR closes that: the record cannot name a commit that does not exist
# yet, and pointing range_head at the pre-squash branch SHA passes the PR's CI and
# then breaks on main where that SHA never existed. (For the ORDINARY order there
# is no deadlock: an open hand-off keeps the milestone incomplete, so no record is
# owed, and the milestone-boundary exemption above already carries flip-then-record
# across two PRs. Verified. This carve-out is only for a record written early.)
#
# THREE CONJUNCTS, and the exemption is the AND of all three. An earlier attempt
# used only the third and was killed in review: reading nothing but "did this one
# commit touch code?" cannot tell "there is no implementation commit" from "the
# implementation commit is elsewhere, possibly outside the range", so it exempted
# ANY item with a roadmap-only flip — a record whose audited range was a single
# empty commit was demonstrated validating with three ordinary items whose code sat
# entirely outside it. Narrowness here is the whole design:
#
#   1. DECLARED. The id is named in the record's `open_at_audit:` list. This is the
#      one half that is a claim rather than a computation, and that is deliberate:
#      it makes "this member was not covered by this audit" an itemised, reviewable
#      line in the record's own diff instead of an inference buried in git.
#   2. IT REALLY WAS AN OPEN HAND-OFF WHEN THE AUDIT RAN. Recomputed from history:
#      the item's status AT range_head must be `attended`. Not the current file —
#      current content is whatever anyone last wrote; the blob at range_head is
#      what the audit could actually have seen. BELT AND BRACES, and named as such:
#      the declaration-validation loop in validate_record applies the same
#      predicate to the same ids first and fails the whole record, so by the time
#      this runs no id that would fail it survives. It is what kills the hole the
#      first attempt opened only in the sense that the pair does; a mutation test
#      deleting THIS line alone leaves the suite green, because the loop above is
#      what the tests catch. Kept anyway, so the exemption does not silently widen
#      if that loop is ever moved or narrowed.
#   3. THE FLIP ADDED NO AUDITABLE SURFACE. Every path in the flip commit is under
#      BACKLOG_DIR. One path outside and the commit carries surface an audit should
#      have read, so the ordinary check applies unchanged.
#
# FAILS CLOSED throughout: an unreadable blob, a missing file at range_head, an
# empty path list (a merge commit prints no names without -m; a bad object, or a
# git that failed, print none either) — every one of those is uncertainty, and
# uncertainty keeps the failure. `--no-renames` so a rename out of the backlog
# lists BOTH paths and the code-side one is seen rather than collapsing to the
# destination name.
hg_status_at() { # hg_status_at <ref> <path> -> the frontmatter `status:` in that blob
  git show "$1:$2" 2>/dev/null \
    | awk '{ sub(/\r$/,"") } NR==1{ if ($0!="---") exit; next } /^---$/{ exit } { print }' \
    | sed -n 's/^status:[[:space:]]*//p' | head -1 | sed 's/[[:space:]]*$//'
}
flip_is_backlog_only() { # flip_is_backlog_only <sha> ; 0 = it changed only BACKLOG_DIR paths
  local sha="$1" paths p n=0
  paths="$(git -c core.quotePath=off show --name-only --format= --no-renames "$sha" 2>/dev/null)" || return 1
  # Heredoc, not a pipe: a `while read` on the right of a pipeline runs in a
  # subshell and `n` would come back 0 no matter what the commit touched.
  while IFS= read -r p; do
    [ -n "$p" ] || continue
    n=$((n + 1))
    case "$p" in "$BACKLOG_DIR"*) : ;; *) return 1 ;; esac
  done <<FLIP_PATHS_EOF
$paths
FLIP_PATHS_EOF
  [ "$n" -gt 0 ]   # no paths => not exempt (see FAILS CLOSED above)
}
handoff_open_at_audit() { # <id> <range_head> <flip-sha> <declared ids> ; 0 = exempt
  local id="$1" head="$2" flip="$3" declared="$4" d
  for d in $declared; do [ "$d" = "$id" ] && break; d=""; done
  [ -n "${d:-}" ] || return 1                                    # (1) declared
  [ "$(hg_status_at "$head" "${BACKLOG_DIR}${id}.md")" = "attended" ] || return 1   # (2) open hand-off then
  flip_is_backlog_only "$flip"                                   # (3) no surface
}

# --- record validation ----------------------------------------------------------
# Task 2 (binding) and Task 3 (triage closure) extend this function. A record
# failing here does NOT crash the gate: the milestone stays in debt and the
# reason is reported.
validate_record() { # validate_record <milestone> <file> ; 0 = valid
  local m="$1" rec="$2"
  local ok=1 k v base head f id flip open_ids unscored
  # Required keys — a record missing provenance/scope fields is not a record.
  for k in sweap_format milestone range_base range_head lens_mode lenses raw refuted confirmed workflow_run journal_sha256; do
    v="$(fm_get "$rec" "$k")"
    [ -n "$v" ] || { fail "record $rec: missing $k:"; ok=0; }
  done
  v="$(fm_get "$rec" sweap_format)"
  [ -z "$v" ] || [ "$v" = "$RECORD_FORMAT" ] \
    || { fail "record $rec: sweap_format: $v but this gate speaks format $RECORD_FORMAT"; ok=0; }
  # A PANEL THAT DID NOT RUN IS NOT AN AUDIT. `unscored:` counts confirmed findings
  # that no refuter ever scored — distinct from `unverified:`, which also covers the
  # legitimate case of a finding reading could not settle. A run whose refuters died
  # on capacity (a consumer's DS.5, 2026-09-02: 330 agents dispatched, 115 failed, 26 of 31
  # "confirmed" findings never scored) emitted a well-formed record that passed every
  # arithmetic check here, because nothing read the number. Writing the gap down was
  # free and it passed; that is the shortcut this refuses.
  #
  # Discharge it either way, and both are honest: resume the run named in
  # `workflow_run:` (its journal caches the completed prefix, so only the dead
  # dispatches are paid for again) and regenerate, or state in `unscored_accepted:`
  # why the milestone is being closed over a panel that did not run.
  #
  # PURELY ADDITIVE: a record with no `unscored:` key validates exactly as before, so
  # records written by a workflow that predates the key are untouched and no
  # sweap_format bump is owed — the same discipline `axes:` and `unverified:` used.
  # PRESENCE, not emptiness: fm_get returns "" both for an absent key and for a
  # key whose value is empty, and `unscored:` with nothing after it is exactly what
  # a broken emitter writes. Treating that as "no key" would open the check on the
  # one input it most needs to catch, so ask the frontmatter whether the key is
  # there at all and let an empty value fall through to the "not a count" arm.
  if frontmatter "$rec" | grep -qE '^unscored:'; then
    unscored="$(fm_get "$rec" unscored)"
    # No arithmetic on a digit string of unbounded length: `[ 99999999999999999999
    # -gt 0 ]` is a shell ERROR, not a comparison, and the `elif` then falls through
    # and the record passes with the complaint on stderr where no --check caller
    # reads it. A pattern test answers "greater than zero" for any width.
    if ! printf '%s' "$unscored" | grep -qE '^[0-9]+$'; then
      fail "record $rec: unscored: '$unscored' is not a count — fail closed"; ok=0
    elif case "$unscored" in *[1-9]*) true ;; *) false ;; esac && [ -z "$(fm_get "$rec" unscored_accepted)" ]; then
      fail "record $rec: unscored: $unscored finding(s) were never scored by any refuter, so this panel did not run for them — resume the run in workflow_run: ($(fm_get "$rec" workflow_run)) and regenerate, or record why you are closing over it in unscored_accepted:"; ok=0
    fi
  fi
  # AN EXPERIMENT THAT RAN AND WAS NOT READ IS NOT EVIDENCE EITHER WAY. `proofs_lost:`
  # counts findings the Validate stage dispatched a prover for and whose verdict never
  # reached the record. A consumer's F12 (2026-09-12): 26 provers ran, the journal held 26
  # execution-backed verdicts (25 confirmed, 1 refuted), and the record said 26
  # UNVERIFIED — triage then filed 22 items to redo experiments already done. The
  # workflow now writes the count down; this is the gate that reads it. Same shape and
  # same discharge as `unscored:`: resume the run in `workflow_run:` and regenerate,
  # or say in `proofs_lost_accepted:` why the milestone closes over it. Same
  # additive discipline: absent key, unchanged behaviour; presence, not emptiness.
  if frontmatter "$rec" | grep -qE '^proofs_lost:'; then
    v="$(fm_get "$rec" proofs_lost)"
    if ! printf '%s' "$v" | grep -qE '^[0-9]+$'; then
      fail "record $rec: proofs_lost: '$v' is not a count — fail closed"; ok=0
    elif case "$v" in *[1-9]*) true ;; *) false ;; esac && [ -z "$(fm_get "$rec" proofs_lost_accepted)" ]; then
      fail "record $rec: proofs_lost: $v experiment(s) were dispatched to a prover and their verdicts never reached the record — resume the run in workflow_run: ($(fm_get "$rec" workflow_run)) and regenerate before triaging (the journal holds the verdicts), or record why you are closing over it in proofs_lost_accepted:"; ok=0
    fi
  fi
  [ "$(fm_get "$rec" milestone)" = "$m" ] || { fail "record $rec: milestone key != $m"; ok=0; }
  base="$(fm_get "$rec" range_base)"; head="$(fm_get "$rec" range_head)"
  # Binding (the mistarget rule): recompute, never trust. Any git uncertainty
  # is a validation failure — fail closed, the milestone stays in debt.
  #
  # A RANGE END MUST BE AN IMMUTABLE OBJECT NAME, NOT A REF. `range_head: HEAD`
  # and `range_head: main` both satisfy every check below — `cat-file -e` resolves
  # them, `is-ancestor base head` holds, and `is-ancestor head HEAD` is trivially
  # true — and then EVERY done-flip is an ancestor of the range, so the done-flip
  # loop further down is a no-op and the whole "this audit covered the milestone's
  # real merges" invariant is vacuous. Demonstrated: a repo with a source file no
  # audit ever read validated with `range_head: HEAD` and failed, correctly, with
  # the same record naming the actual commit.
  #
  # This is not a hand-editing scenario. milestone-audit.js assembles the record
  # mechanically — `String(scope?.range).split('..')` — and the Scope stage's
  # schema asks only for "the resolved commit range, <base>..<head>", so a scope
  # agent that answers `main..HEAD`, or a caller passing that as `{range}`, ships a
  # record with a ref in it and no human in the loop. (The workflow now demands
  # full SHAs; this is the enforcement, because a prompt is not one.)
  #
  # A ref is also not DURABLE, which is the deeper reason: the record is a claim
  # about a fixed range, and post-merge-auditcheck re-runs --check later against a
  # moved HEAD. A record whose meaning changes between two runs of the same check
  # is not a record.
  #
  # The rule: 40 lowercase hex digits that resolve to THEMSELVES as a commit. That
  # rejects every ref and every abbreviation, and rejects a tag's own object id
  # (which peels to a different sha) while accepting the commit it points at. All
  # four records in the consumer repos already satisfy it — checked before shipping
  # — so this tightens the contract without wedging anyone.
  if [ -n "$base" ] && [ -n "$head" ]; then
    for k in base head; do
      eval "v=\$$k"
      if ! printf '%s' "$v" | grep -qE '^[0-9a-f]{40}$'; then
        fail "record $rec: range_$k must be a full 40-character commit SHA, not '$v' — a ref (HEAD, a branch, a tag) makes the range binding vacuous and means something different every time this check runs"; ok=0
      elif [ "$v" != "$(git rev-parse --verify "$v^{commit}" 2>/dev/null)" ]; then
        fail "record $rec: range_$k ($v) does not name a commit in this repo"; ok=0
      fi
    done
    git cat-file -e "$base^{commit}" 2>/dev/null || { fail "record $rec: range_base is not a commit here"; ok=0; }
    git cat-file -e "$head^{commit}" 2>/dev/null || { fail "record $rec: range_head is not a commit here"; ok=0; }
    if [ "$ok" = 1 ]; then
      git merge-base --is-ancestor "$base" "$head" 2>/dev/null || { fail "record $rec: range_base is not an ancestor of range_head"; ok=0; }
      git merge-base --is-ancestor "$head" HEAD 2>/dev/null || { fail "record $rec: range_head is not an ancestor of HEAD"; ok=0; }
    fi
    if [ "$ok" = 1 ]; then
      # Every done item of M must have completed WITHIN the audited range:
      # the commit that introduced its `status: done` (oldest -S hit) must be
      # reachable from range_head. This is what makes "audited F1's real
      # merges" checkable — an audit of a stale range fails structurally.
      #
      # The item set comes from the single ITEMS scan above (same files, same
      # glob order) — the follow-up exclusion and the done filter are the same
      # two predicates, applied to already-parsed rows instead of re-spawning
      # basename+fm_get per file. Follow-up items created by an audit's triage
      # are DEBT OF the milestone, not members of it, so their later completion
      # must not retroactively fail the record.
      #
      # The pickaxe stays PER PATH, on purpose, and a 2026-09-23 attempt to
      # batch it is why this comment is long. A directory-wide
      # `git log --name-only -S -- <backlog dir>` lists, per commit, exactly the
      # paths whose match count changed (diffcore-pickaxe without --pickaxe-all),
      # and on linear history the last commit a path appears under IS its oldest
      # per-path hit — 41 of 41 on a consumer repo. But git's default history
      # simplification is decided PER PATHSPEC: a merge that is TREESAME to one
      # parent for roadmap/F1.1.md is followed along that parent only, while for
      # `-- roadmap/` the same merge is TREESAME to neither parent and BOTH sides
      # are walked. So a branch that flipped F1.1 done, merged with F1.1 put back
      # to todo, and a mainline flip AFTER the audit: per path the flip is the
      # mainline commit (outside the range, record fails, correctly); directory-
      # wide the branch-side flip is older, reachable, and the record validates.
      # Fail-open on the one shape this check exists for; the mirror shape fails
      # closed on a record that was valid. Reproduced before shipping; the memo
      # records it. What IS batched, exactly: the ancestry test below.
      # The declared carve-out (see "the open hand-off carve-out" above). Every id
      # named here is validated on its own terms whether or not it is done yet: a
      # declaration that names a file that does not exist, or an item that was not
      # actually an open hand-off at range_head, is a false statement in the record
      # and fails it — the list cannot be a place to park ids that might come in
      # useful later.
      # set -f while splitting: these are word-split unquoted, and an entry like
      # `*` would otherwise glob against the repo root. Every expansion is then
      # required to be an item file that was `attended` at range_head, so a glob
      # fails the record loudly rather than widening anything — but not expanding
      # is cheaper than relying on that.
      set -f
      open_ids="$(fm_get "$rec" open_at_audit | tr -d '[]' | tr ',' ' ')"
      for id in $open_ids; do
        if [ ! -f "${BACKLOG_DIR}${id}.md" ]; then
          fail "record $rec: open_at_audit names $id but ${BACKLOG_DIR}${id}.md does not exist"; ok=0
        elif [ "$(hg_status_at "$head" "${BACKLOG_DIR}${id}.md")" != "attended" ]; then
          fail "record $rec: open_at_audit names $id but it was not an open hand-off at range_head (status there: '$(hg_status_at "$head" "${BACKLOG_DIR}${id}.md")')"; ok=0
        fi
      done
      set +f
      local done_ids reach id flip
      done_ids="$(printf '%s' "$ITEMS" | awk -F'\t' -v m="$m" '$1 == "0" && $2 == m && $4 == "done" { print $3 }')"
      if [ -n "$done_ids" ]; then
        # ONE `git rev-list <range_head>` per record in place of one
        # `git merge-base --is-ancestor <flip> <range_head>` per done item: a
        # commit is an ancestor of range_head (range_head included) exactly when
        # it is in that list, and a 40-hex sha can only match a whole line of it.
        # A rev-list that printed nothing puts every flip outside — closed.
        reach="$(git rev-list "$head" 2>/dev/null)"
        while IFS= read -r id; do
          [ -n "$id" ] || continue
          f="${BACKLOG_DIR}${id}.md"
          # `-c log.follow=false`: a user's `log.follow = true` changed this
          # answer in the 2026-09-23 refutation; `--literal-pathspecs`: a path,
          # never a pattern.
          flip="$(git -c log.follow=false --literal-pathspecs log --format=%H -S'status: done' -- "$f" 2>/dev/null | tail -1)"
          if [ -z "$flip" ]; then
            fail "record $rec: cannot locate the commit that completed $id (uncommitted flip?) — fail closed"; ok=0
            continue
          fi
          case "$reach" in *"$flip"*) continue ;; esac
          # Unreachable — unless this is a hand-off the record DECLARED was still
          # open when the audit ran, which really was `attended` at range_head, and
          # whose flip added no surface. All three, or the failure stands.
          handoff_open_at_audit "$id" "$head" "$flip" "$open_ids" && continue
          fail "record $rec: $id completed outside the audited range (flip $flip not reachable from range_head)"; ok=0
        done <<DONE_ITEMS_EOF
$done_ids
DONE_ITEMS_EOF
      fi
    fi
  fi

  # --- triage closure: counts add up and every confirmed finding lands somewhere
  local raw refuted confirmed body blocks dispo ref reftype reffile finders
  raw="$(fm_get "$rec" raw)"; refuted="$(fm_get "$rec" refuted)"; confirmed="$(fm_get "$rec" confirmed)"
  case "$raw$refuted$confirmed" in *[!0-9]*) fail "record $rec: raw/refuted/confirmed must be numeric"; ok=0 ;; esac
  if [ "$ok" = 1 ] && [ "$raw" -ne $((refuted + confirmed)) ]; then
    fail "record $rec: raw ($raw) != refuted ($refuted) + confirmed ($confirmed)"; ok=0
  fi

  # --- "this audit ran", which is not the same claim as "this audit was clean"
  # A zero-findings record is the one shape that satisfies every other check here
  # while asserting nothing at all: 0 == 0 + 0, no blocks to dispose of, binding
  # intact, required keys present (`raw: 0` is non-empty). It is also exactly
  # what a totally BROKEN run produces — a consumer's F11 audit lost all eleven finder
  # agents to an unresolvable agent type, and the record that fell out of that
  # would have passed here as a clean milestone.
  #
  # So a record claiming zero findings must carry affirmative evidence of work:
  # `finders_reporting`, the number of lenses that actually returned a result,
  # emitted by the workflow itself (which now refuses to return at all when that
  # number is 0). Demanded ONLY when raw is 0, so every record written before the
  # key existed still validates — purely additive, no sweap_format bump, the same
  # move `axes:` and `unverified:` made.
  #
  # Scoped to the PRIMARY axis on purpose. A `ui.raw: 0` comes from a different
  # workflow (the Tier-2 UI critique, deliberately frozen as a control), and this
  # gate does not get to invent keys for a producer that does not emit them.
  if [ "$ok" = 1 ] && [ "$raw" -eq 0 ]; then
    finders="$(fm_get "$rec" finders_reporting)"
    case "$finders" in
      "") fail "record $rec: raw: 0 but no finders_reporting: — a zero-findings record is indistinguishable from a run whose finders all died, so it must state how many lenses actually reported. Re-run the audit with a current plugin, or add finders_reporting: <n> if you can attest they ran."; ok=0 ;;
      *[!0-9]*) fail "record $rec: finders_reporting must be numeric"; ok=0 ;;
      *) [ "$finders" -ge 1 ] || { fail "record $rec: finders_reporting: 0 — this audit reported nothing because nothing ran; it is not a clean milestone"; ok=0; } ;;
    esac
  fi

  # --- additional audit axes -----------------------------------------------
  # A milestone can be audited on more than one axis: the code audit plus, for a
  # UI-heavy milestone, a Tier-2 UI audit (playbook, "UI audit"). Those are
  # SEPARATE runs with their own lens sets, their own stats and their own
  # journals — a consumer's F9 was audited 54/34/20 on code and 11/9/2 on UI, and the
  # single stat set here could only describe one of them, leaving the UI
  # survivors (FK.4, FK.5) as disposition blocks that no `confirmed` count
  # accounted for.
  #
  # The unprefixed keys describe the PRIMARY audit. `axes: [ui, ...]` declares
  # additional ones, each carrying the same seven keys under an `<axis>.` prefix.
  # Flat, single-line, inline lists — the format contract is intact and no YAML
  # parser appears here (same rule as roadmap-lint.sh).
  #
  # PURELY ADDITIVE: a record with no `axes:` key validates exactly as before, so
  # this does NOT bump sweap_format. Adding an optional key that invalidates
  # nothing is the kind of change the version exists to make unnecessary.
  local axes ax axkey axraw axref axconf k2 total_confirmed
  total_confirmed="$confirmed"
  axes="$(fm_get "$rec" axes | tr -d '[]' | tr ',' ' ')"
  for ax in $axes; do
    # Axis names are restricted so an axis can never inject regex into the key
    # lookups below (fm_get builds a sed pattern from the key).
    case "$ax" in
      *[!a-z0-9-]*|"" ) fail "record $rec: axis '$ax' must be lowercase [a-z0-9-]"; ok=0; continue ;;
    esac
    axkey="$ax\\."
    for k2 in raw refuted confirmed lens_mode lenses workflow_run journal_sha256; do
      [ -n "$(fm_get "$rec" "$axkey$k2")" ] || { fail "record $rec: axis '$ax' is declared but $ax.$k2: is missing"; ok=0; }
    done
    axraw="$(fm_get "$rec" "${axkey}raw")"
    axref="$(fm_get "$rec" "${axkey}refuted")"
    axconf="$(fm_get "$rec" "${axkey}confirmed")"
    case "$axraw$axref$axconf" in
      ""|*[!0-9]*) fail "record $rec: $ax.raw/$ax.refuted/$ax.confirmed must be numeric"; ok=0; continue ;;
    esac
    if [ "$axraw" -ne $((axref + axconf)) ]; then
      fail "record $rec: $ax.raw ($axraw) != $ax.refuted ($axref) + $ax.confirmed ($axconf)"; ok=0; continue
    fi
    total_confirmed=$((total_confirmed + axconf))
  done
  body="$(awk '{ sub(/\r$/,"") } NR==1 && $0=="---" { infm=1; next } infm && /^---$/ { infm=0; next } !infm { print }' "$rec")"
  blocks="$(printf '%s\n' "$body" | grep -c '^### ' || true)"
  # Blocks are DISPOSITIONS, not findings, and the two have different
  # cardinalities: a multi-lens ensemble converging on one defect is the normal
  # case (a consumer's F9: six lenses hit the same claim-lease bug — the record called
  # that convergence "the strongest signal this audit produced"). Requiring one
  # block per confirmed finding would force that correct collapse to be undone
  # into six blocks saying the same thing. So `defects:` may declare the distinct
  # count after collapse; blocks are matched against THAT. It defaults to
  # `confirmed` (no collapse), which keeps every pre-existing record valid.
  # A collapse can only ever merge, never invent: 0 < defects <= confirmed.
  # Blocks are matched against `defects` (distinct defects after collapse), which
  # is bounded by the survivors of EVERY axis — a UI-audit survivor is a real
  # finding that must be allowed its own disposition block.
  local defects
  defects="$(fm_get "$rec" defects)"
  if [ -n "$defects" ]; then
    case "$defects" in *[!0-9]*) fail "record $rec: defects must be numeric"; ok=0 ;; esac
    if [ "$ok" = 1 ] && { [ "$defects" -gt "$total_confirmed" ] || { [ "$defects" -eq 0 ] && [ "$total_confirmed" -gt 0 ]; }; }; then
      fail "record $rec: defects ($defects) must be >0 and <= total confirmed across all axes ($total_confirmed) — collapsing merges findings, it never invents or drops them"; ok=0
    fi
  else
    defects="$total_confirmed"
  fi
  if [ "$ok" = 1 ] && [ "$blocks" -ne "$defects" ]; then
    fail "record $rec: $blocks finding block(s) but $defects distinct defect(s) expected (total confirmed across all axes: $total_confirmed$([ -n "$(fm_get "$rec" defects)" ] && printf ', collapsed via defects:'))"; ok=0
  fi
  # One disposition per block, each resolvable. Blocks are separated by ^###
  # headers; a disposition line is `disposition: fix_pr #N | followup <id> |
  # blocked <id>`. Count and validate per block via awk block-splitting.
  if [ "$blocks" -gt 0 ]; then
    # A record names the same follow-up under several blocks (a consumer's F12: 51
    # disposition lines over 25 distinct ids), and every check on a referenced
    # file — existence, followup_of, status, roadmap-lint — is a function of the
    # file, so each (kind, id) pair is judged once. 26 of a consumer's 91 lint runs
    # per gate call were repeats.
    local n=0 checked=""
    while [ "$n" -lt "$blocks" ]; do
      n=$((n + 1))
      dispo="$(printf '%s\n' "$body" | awk -v want="$n" '/^### /{b++} b==want && /^disposition:[[:space:]]/{ sub(/^disposition:[[:space:]]*/,""); print }')"
      if [ "$(printf '%s\n' "$dispo" | grep -c '[^[:space:]]')" -ne 1 ]; then
        fail "record $rec: finding block $n needs exactly one disposition: line"; ok=0; continue
      fi
      case "$dispo" in
        "fix_pr #"[0-9]*) : ;;
        "followup "*|"blocked "*)
          reftype="${dispo%% *}"; ref="${dispo#* }"
          reffile="${BACKLOG_DIR}${ref}.md"
          case "|$checked|" in *"|$reftype $ref|"*) continue ;; esac
          checked="${checked:+$checked|}$reftype $ref"
          if [ ! -f "$reffile" ]; then
            fail "record $rec: disposition references $ref but ${reffile} does not exist"; ok=0
          else
            [ "$(fm_get "$reffile" followup_of)" = "$m" ] || { fail "record $rec: $ref must carry followup_of: $m"; ok=0; }
            if [ "$reftype" = "blocked" ]; then
              [ "$(fm_get "$reffile" status)" = "blocked" ] || { fail "record $rec: $ref disposition says blocked but its status is not"; ok=0; }
            fi
            bash "$(dirname "${BASH_SOURCE[0]}")/roadmap-lint.sh" "$reffile" >/dev/null 2>&1 \
              || { fail "record $rec: $ref fails roadmap-lint"; ok=0; }
          fi
          ;;
        *) fail "record $rec: finding block $n has malformed disposition '$dispo'"; ok=0 ;;
      esac
    done
  fi

  [ "$ok" = 1 ]
}

# --- debt set -------------------------------------------------------------------
DEBT=""
while IFS= read -r m; do
  [ -n "$m" ] || continue
  in_baseline "$m" && continue
  rec="${BACKLOG_DIR}audits/$m.md"
  if [ ! -f "$rec" ]; then
    # The milestone boundary (see above). Exempt in BOTH modes, not just --check:
    # the CI job runs --files against the PR's own checkout too, where this
    # milestone reads complete and the PR touches the very item file that
    # completed it — so a --check-only exemption would still deny the merge in
    # merge mode and leave the deadlock fully intact.
    if newly_complete "$m"; then
      [ "$MODE" = "--check" ] && printf 'DEFERRED: milestone %s becomes complete in the state under review, so its audit cannot have run yet (the audit reads the MERGED default branch). Not debt here. It becomes debt the instant this lands: no backlog-advancing PR will pass the gate afterwards until %saudits/%s.md exists and validates. Run /milestone-audit for %s once this is on main.\n' "$m" "$BACKLOG_DIR" "$m" "$m"
      continue
    fi
    DEBT="$DEBT$m"$'\n'
    [ "$MODE" = "--check" ] && fail "milestone $m is complete but has no audit record ($rec) — run /milestone-audit for it"
  elif ! rec_out="$(validate_record "$m" "$rec")"; then
    DEBT="$DEBT$m"$'\n'
    if [ "$MODE" = "--check" ]; then
      [ -n "$rec_out" ] && printf '%s\n' "$rec_out"
      fails=1
    fi
  fi
done <<COMPLETE_EOF
$COMPLETE
COMPLETE_EOF

# --- hand-off provenance: `attended` is AUTHORED, never TRANSITIONED into --------
# A hand-off item (`status: attended`) says "this was always the human's to do".
# The failure mode it creates is an agent relabelling its OWN stuck work as human
# work: the goal template stops a run when only [blocked] and [attended] items
# remain, so the flip converts an unfinished item into a legitimate termination
# condition — and unlike [blocked] it carries no failure signal. That is the
# textbook shape of a reward-hacked shortcut (2026-08-16 research memo, §3), and
# the same memo's other finding is why this is a check and not a rule: prompts
# telling a model not to take a shortcut are advisory and can even increase the
# behaviour, while a deterministic check simply holds.
#
# The rule: for every item currently `attended`, the commit that introduced
# `status: attended` must BE the commit that added the file. Authoring a hand-off
# is legal; converting existing work into one is not. Provenance comes from git,
# not from file content, so it cannot be forged by editing the item.
#
# The legitimate human move this forbids — "actually, F2.3 is mine now" — has a
# supported path: archive F2.3 with a dropped_reason: and author the hand-off as a
# new item. Both halves are visible in the diff, which is the point.
#
# Uncommitted files are skipped, not failed: /roadmap lints items in the working
# tree before they are ever committed, and an unborn item has no provenance to
# judge. CI runs this on the PR's own checkout, where the commits do exist.
if [ "$MODE" = "--check" ]; then
  # Same item set as before (ITEMS is the one scan of the working tree, in glob
  # order); only the per-file status lookup moved into that scan. Follow-up
  # items are NOT excluded here — a hand-off is judged wherever it lives.
  while IFS="$TAB" read -r _fu _ms id status; do
    [ -n "$id" ] || continue
    [ "$status" = "attended" ] || continue
    f="${BACKLOG_DIR}${id}.md"
    added="$(git log --diff-filter=A --format=%H -- "$f" 2>/dev/null | tail -1)"
    became="$(git log --format=%H -S'status: attended' -- "$f" 2>/dev/null | tail -1)"
    [ -n "$added" ] && [ -n "$became" ] || continue   # not committed yet — nothing to judge
    [ "$added" = "$became" ] && continue
    fail "hand-off $id: status: attended was introduced by $became but the item file was added by $added — an attended item is AUTHORED, never transitioned into (an agent must not relabel stuck work as human work; stuck work is [blocked]). If this is a deliberate re-assignment, archive $id with a dropped_reason: and author the hand-off as a new item."
  done <<ATTENDED_EOF
$ITEMS
ATTENDED_EOF

  # --- blocked-question aging: INFORMATIONAL, never a failure ------------------
  # A [blocked] item is a question waiting on a human. Unlike audit debt, an
  # unanswered direction call is LEGITIMATELY deferrable — the cost of waiting is
  # real but bounded, and blocking a build on someone's taste call would be
  # crying wolf. So this prints and never fails; `AGING:` joins `DEFERRED:` as a
  # non-failing prefix.
  #
  # Why it lives here at all, when the board and the run summary already list
  # blocked items: those are read-only displays, and a consumer proved they change
  # nothing (2026-08-16 research memo — five of six questions survived a whole
  # milestone authoring cycle unasked). The evidence there says the intervention
  # that works is a documented pending-state AT THE TRANSITION, and this gate is
  # already what /roadmap runs as its pre-flight at exactly that moment. Riding
  # on plumbing the boundary already reads beats a fourth place to look.
  #
  # It is surfacing, not enforcement, and deliberately so: skipping the carry
  # increment buys an agent nothing it wants, so it is not the shortcut shape
  # that earns a mechanism here (contrast the hand-off provenance check above).
  while IFS="$TAB" read -r _fu _ms id status; do
    [ -n "$id" ] || continue
    [ "$status" = "blocked" ] || continue
    f="${BACKLOG_DIR}${id}.md"
    carried="$(fm_get "$f" carried)"
    case "$carried" in ""|*[!0-9]*) carried=0 ;; esac
    # `blocked:` is usually written already-quoted (the question contains colons
    # and commas), so strip one surrounding pair before truncating — otherwise
    # the line reads ""Should the row…" with a doubled quote.
    q="$(fm_get "$f" blocked | sed 's/^"//; s/"$//' | cut -c1-100)"
    if [ "$carried" -ge 2 ]; then
      printf 'AGING: blocked %s — carried %s milestone boundaries: "%s…". At carried 2 this is ASKED, not offered: /roadmap will not start the next brainstorm until it is answered, defaulted on your explicit say-so, or dropped with a dropped_reason:. Answer it now with /unblock %s.\n' "$id" "$carried" "$q" "$id"
    else
      printf 'AGING: blocked %s — carried %s milestone boundary(ies): "%s…". Answer it with /unblock %s; at carried 2 it stops being optional.\n' "$id" "$carried" "$q" "$id"
    fi
  done <<BLOCKED_EOF
$ITEMS
BLOCKED_EOF

  exit "$fails"
fi

# --- merge mode (--files): roadmap-scoped denial --------------------------------
# Deny iff debt exists AND the PR touches top-level item files AND it does not
# discharge the debt (contain the audit record for a debt milestone). Follow-up
# and blocked items ride the same PR as the record, so discharge is detected at
# PATH level here.
#
# WHY PATH LEVEL IS ALL THIS MODE CAN DO: --files runs inside the pre-merge hook,
# against the LOCAL checkout, which does not contain the PR's version of the
# record — the record being discharged is by definition not merged yet. This mode
# is a ROUTING decision ("does this PR carry the record?"), never a validity
# decision. Validity is decided by --check, in a checkout that actually holds the
# content:
#   1. the audit-gate CI job (templates/.github/workflows/audit-gate.yml) runs
#      --check on the PR's own checkout, so a malformed record fails the record
#      PR itself, before it can merge. This is the primary control.
#   2. post-merge-auditcheck.sh re-runs --check on the freshly-pulled mainline
#      right after any merge, so a repo whose CI job is missing still learns
#      within ONE PR instead of drifting for days.
# A consumer's 2026-08-11 miss (F9's prose-only record merged, F10 authored on top)
# is what this note exists for: the old comment deferred to "the next --check"
# while nothing was scheduled to run one. Do not weaken (1) or (2) and leave this
# deferral standing on its own.
[ -n "$(printf '%s' "$DEBT")" ] || exit 0
touches_items=0; discharges=0
for f in "$@"; do
  # Note: case patterns are STRING matches where * also matches / (not filesystem globs)
  case "$f" in
    "${BACKLOG_DIR}audits/"*.md)
      m="$(basename "$f" .md)"
      while IFS= read -r d; do [ "$m" = "$d" ] && discharges=1; done <<DEBT_EOF
$DEBT
DEBT_EOF
      ;;
    "${BACKLOG_DIR}"*/*) : ;;              # other subdirs (ideas/, discovered/, archive/) — not item files; a discovered note is gate-exempt BY THIS ARM (playbook "Discovered work")
    "${BACKLOG_DIR}"*.md) touches_items=1 ;;
  esac
done
if [ "$touches_items" = 1 ] && [ "$discharges" = 0 ]; then
  debt_list="$(printf '%s' "$DEBT" | tr '\n' ' ')"
  fail "audit debt exists for milestone(s): ${debt_list}— this PR advances the backlog without discharging it. Run /milestone-audit and land its record (+ follow-ups) first; code-only PRs are unaffected."
fi
exit "$fails"
